@Component
public class TraceProperties {
    private final List<String> patterns = List.of("order*", "find*");
    public List<String> getPatterns() { return patterns; }
}

@Bean
public Advisor logTraceAdvisor(LogTrace trace, TraceProperties props) {
    NameMatchMethodPointcut pointcut = new NameMatchMethodPointcut();
    pointcut.setMappedNames(props.getPatterns().toArray(String[]::new));
    return new DefaultPointcutAdvisor(pointcut, new LogTraceAdvice(trace));
}

