-- 네 관문을 한 번에 훑는다

@GetMapping(value = "/proxy/why", produces = "text/plain")
String why(String name) {
    if (!ctx.containsBean(name)) return "① 빈이 아니다\n";
    Object bean = ctx.getBean(name);
    if (AopUtils.isAopProxy(bean)) return "감싸졌다\n";

    Class<?> clazz = bean.getClass();
    for (Advisor a : ctx.getBeansOfType(Advisor.class).values()) {
        if (!(a instanceof PointcutAdvisor pa)) continue;
        if (!pa.getPointcut().getClassFilter().matches(clazz))
            return "③ 클래스가 안 맞는다\n";
        long n = Arrays.stream(clazz.getMethods())
            .filter(m -> pa.getPointcut().getMethodMatcher().matches(m, clazz))
            .count();
        if (n == 0) return "④ 걸리는 메서드가 없다\n";
    }
    return "② 너무 일찍 만들어졌다\n";
}

