@Component
class EligibilityCheck implements InitializingBean {
    private static final List<String> MUST = List.of(
        "orderServiceV3", "orderRepositoryV3", "configLoader", "txHelper");

    @Override
    public void afterPropertiesSet() {
        for (String name : MUST) {
            Object bean = ctx.getBean(name);
            if (!AopUtils.isAopProxy(bean))
                throw new IllegalStateException("안 감싸짐: " + name);
        }
    }
}

